char *ndcache_state2str(short state) { char *cp = "UNKNOWN"; switch (state) { case ND6_LLINFO_INCOMPLETE: cp = "ND6_LLINFO_INCOMPLETE"; break; case ND6_LLINFO_PURGE: cp = "ND6_LLINFO_PURGE"; break; case ND6_LLINFO_NOSTATE: cp = "ND6_LLINFO_NOSTATE"; break; case ND6_LLINFO_PROBE: cp = "ND6_LLINFO_PROBE"; break; case ND6_LLINFO_STALE: cp = "ND6_LLINFO_STALE"; break; case ND6_LLINFO_REACHABLE: cp = "ND6_LLINFO_REACHABLE"; break; case ND6_LLINFO_INCOMPLETE: cp = "ND6_LLINFO_INCOMPLETE"; break; default: break; } return cp; }